from bagimlilik.bagimlilik import kurulum_sirasi, DonguHatasi

# Test 1: Basit sıralama
deps1 = {"A": [], "B": ["A"], "C": ["A", "B"]}
try:
    print(f"Test 1 Sonuç: {kurulum_sirasi(deps1)}")
except Exception as e:
    print(f"Test 1 Hata: {e}")

# Test 2: Birden fazla başlangıç noktası (Alfabetik kontrol)
deps2 = {"C": ["A"], "B": ["A"], "A": []}
try:
    # A ilk olmalı, sonra B ve C alfabetik sırayla
    print(f"Test 2 Sonuç: {kurulum_sirasi(deps2)}")
except Exception as e:
    print(f"Test 2 Hata: {e}")

# Test 3: Döngü (A->B, B->A)
deps3 = {"A": ["B"], "B": ["A"]}
try:
    print(f"Test 3 Sonuç: {kurulum_sirasi(deps3)}")
except DonguHatasi as e:
    print(f"Test 3 Döngü Yakalandı: {e.dongu}")
except Exception as e:
    print(f"Test 3 Genel Hata: {e}")

# Test 4: Bağımlılık sadece bir yerde geçiyor
deps4 = {"X": ["Y"]}
try:
    print(f"Test 4 Sonuç: {kurulum_sirasi(deps4)}")
except Exception as e:
    print(f"Test 4 Hata: {e}")

# Test 5: Kendine bağımlılık (Döngü kuralı)
deps5 = {"X": ["X"]}
try:
    print(f"Test 5 Sonuç: {kurulum_sirasi(deps5)}")
except DonguHatasi as e:
    print(f"Test 5 Döngü Yakalandı: {e.dongu}")
except Exception as e:
    print(f"Test 5 Genel Hata: {e}")
